using System.Reflection;
using System.Runtime.Loader;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Seamless.FLinq;

namespace Test.SourceGenerator.LastDemandSupplement;

// 独立候補。全runtime/compileは未実行。
[LinqIntercept(false)]
public sealed class Last{
    private static readonly string[] Modes=["All","None","CounterOnly"];
    private static readonly string[] QueryNames=[
        "select-where-last","where-select-last","where-select-where-last","select-where-select-last","where-last-predicate","select-last-predicate","indexed-where-last","indexed-select-last","ilist-last-predicate","ilist-lastordefault-predicate","ilist-where-last","ilist-where-lastordefault","ilist-select-last","ilist-where-select-last","range-where-lastordefault","range-lastordefault-predicate","mutation-list-last","mutation-list-lastordefault","mutation-list-where-last","mutation-list-where-lastordefault","mutation-list-where-select-last","reverse-last-terminal-predicate","ordered-last-terminal-predicate"
    ];
    private const string FalseBytes="""""";
    private const string TrueBytes="""""";

    [Fact]
    public void SupplementCasesAgainstSystemOracle(){
        var failures=new List<string>();
        var originalInputBytes=new[]{Convert.FromBase64String(FalseBytes),Convert.FromBase64String(TrueBytes)};
        var originalInputHashes=originalInputBytes.Select(bytes=>Convert.ToHexString(SHA256.HashData(bytes))).ToArray();
        var inputBytes=originalInputBytes.Select(bytes=>{
            var source=Encoding.UTF8.GetString(bytes);
            // System oracleと生成対象のRangeを同じSystem型へ束縛する。
            source=source.Replace("using System.Linq;","using System.Linq;\nusing Enumerable=global::System.Linq.Enumerable;",StringComparison.Ordinal);
            return Encoding.UTF8.GetBytes(source);
        }).ToArray();
        var inputHashes=inputBytes.Select(bytes=>Convert.ToHexString(SHA256.HashData(bytes))).ToArray();
        var textInputs=inputBytes.Select(bytes=>Encoding.UTF8.GetString(bytes)).ToArray();
        var expectedCases=BuildCases();
        SaveInputAudit(inputBytes,inputHashes,originalInputHashes,expectedCases.Count);
        var cellCount=0;
        for(var anchor=0;anchor<2;anchor++){
            var source=textInputs[anchor];
            var (compilation,generated,diagnostics,errors)=Generate(source,anchor==1);
            SaveGeneration(anchor,source,generated,diagnostics,errors,inputHashes[anchor],"NotAttempted");
            failures.AddRange(errors.Select(error=>$"anchor={anchor}: {error}"));
            if(errors.Count!=0){continue;}
            var anchorObservations=new List<object>();
            try{
                using var pe=new MemoryStream();
                var emit=compilation.Emit(pe);
                diagnostics.AddRange(emit.Diagnostics.Select(diagnostic=>diagnostic.ToString()));
                if(!emit.Success){
                    var emitErrors=emit.Diagnostics.Where(diagnostic=>diagnostic.Severity==DiagnosticSeverity.Error).Select(diagnostic=>diagnostic.ToString()).ToArray();
                    failures.AddRange(emitErrors.Select(error=>$"anchor={anchor}: Emit: {error}"));
                    SaveGeneration(anchor,source,generated,diagnostics,emitErrors.ToList(),inputHashes[anchor],"Failed");
                    continue;
                }
                SaveGeneration(anchor,source,generated,diagnostics,[],inputHashes[anchor],"Passed");
                pe.Position=0;
                var context=new AssemblyLoadContext("LastSupplement"+anchor,isCollectible:true);
                try{
                    var probe=context.LoadFromStream(pe).GetType("Sample.LastDemandProbe")!;
                    var run=probe.GetMethod("Run",BindingFlags.Public|BindingFlags.Static)!;
                    foreach(var item in expectedCases){
                        var system=(object[])run.Invoke(null,[3,item.ID,item.Failure,item.Mutation])!;
                        for(var mode=0;mode<3;mode++){
                            var actual=(object[])run.Invoke(null,[mode,item.ID,item.Failure,item.Mutation])!;
                            cellCount++;
                            var contextLabel=$"anchor={anchor}/{QueryNames[item.ID]}/failure={item.Failure}/mutation={item.Mutation}/{Modes[mode]}";
                            var differences=Compare(system,actual,anchor==1||mode!=0);
                            failures.AddRange(differences.Select(difference=>contextLabel+": "+difference));
                            var tracePolicy="PerEventUpperBound";
                            if(anchor==1||mode!=0){tracePolicy="Exact";}
                            anchorObservations.Add(new{QueryID=item.ID,Query=QueryNames[item.ID],item.Failure,item.Mutation,Mode=Modes[mode],TracePolicy=tracePolicy,Differences=differences,System=Snapshot(system),Actual=Snapshot(actual)});
                        }
                    }
                }finally{context.Unload();}
            }catch(Exception exception){failures.Add($"anchor={anchor}: Runtime: {exception}");}
            SaveRuntime(anchor,anchorObservations,cellCount,inputHashes[anchor]);
        }
        Assert.Equal(414,cellCount);
        Assert.True(failures.Count==0,string.Join(Environment.NewLine,failures));
    }

    private static List<(int ID,int Failure,int Mutation)> BuildCases(){
        var cases=new List<(int ID,int Failure,int Mutation)>();
        for(var id=0;id<23;id++){
            if(id>=16&&id<=20){
                for(var mutation=1;mutation<=3;mutation++){cases.Add((id,0,mutation));}
            }else{
                for(var failure=0;failure<=2;failure++){cases.Add((id,failure,0));}
            }
        }
        return cases;
    }

    private static (CSharpCompilation Compilation,string Generated,List<string> Diagnostics,List<string> Errors) Generate(string source,bool anchored){
        var options=new CSharpParseOptions(LanguageVersion.Preview).WithFeatures([
            new("InterceptorsPreview","true"),new("InterceptorsNamespaces","Intercept"),new("InterceptorsPreviewNamespaces","Intercept")
        ]);
        var compilation=GeneratorTestHelpers.CreateCompilation([("LastDemandSupplement.cs",source)]).WithAssemblyName("LastDemandSupplement"+anchored);
        compilation=compilation.ReplaceSyntaxTree(compilation.SyntaxTrees.Single(),CSharpSyntaxTree.ParseText(source,options,path:"LastDemandSupplement.cs"));
        GeneratorDriver driver=CSharpGeneratorDriver.Create([new global::Seamless.FLinq.Generator.FLinqIncrementalGenerator().AsSourceGenerator()],parseOptions:options);
        driver=driver.RunGeneratorsAndUpdateCompilation(compilation,out var output,out var generatorDiagnostics);
        var all=generatorDiagnostics.Concat(output.GetDiagnostics()).ToArray();
        var diagnostics=all.Select(diagnostic=>diagnostic.ToString()).ToList();
        var generated=string.Concat(output.SyntaxTrees.Skip(1).Select(tree=>tree.ToString()));
        var errors=all.Where(diagnostic=>diagnostic.Severity==DiagnosticSeverity.Error).Select(diagnostic=>diagnostic.ToString()).ToList();
        for(var mode=0;mode<3;mode++){
            for(var id=0;id<QueryNames.Length;id++){
                var prefix="OptimizedLinq_";
                if(mode==2){prefix="MeasuredLinq_";}
                if(!generated.Contains(prefix+"Query"+mode+"_"+id+"_",StringComparison.Ordinal)){errors.Add("InterceptionMiss: Query"+mode+"_"+id);}
            }
        }
        return ((CSharpCompilation)output,generated,diagnostics,errors);
    }

    private static List<string> Compare(object[] expected,object[] actual,bool exactTrace){
        var differences=new List<string>();
        string[] columns=["Value","ExceptionType","ExceptionMessage"];
        for(var index=0;index<columns.Length;index++){
            if(!Equals(expected[index],actual[index])){differences.Add(columns[index]+": expected="+expected[index]+", actual="+actual[index]);}
        }
        var expectedTrace=(string[])expected[3];
        var actualTrace=(string[])actual[3];
        if(exactTrace){
            if(!expectedTrace.SequenceEqual(actualTrace)){differences.Add("Trace: expected="+string.Join(",",expectedTrace)+", actual="+string.Join(",",actualTrace));}
        }else{
            var counts=new Dictionary<string,int>(StringComparer.Ordinal);
            foreach(var token in expectedTrace){counts.TryGetValue(token,out var count);counts[token]=count+1;}
            foreach(var token in actualTrace){
                if(!counts.TryGetValue(token,out var count)||count==0){differences.Add("EvaluationUpperBound: "+token);}
                else{counts[token]=count-1;}
            }
        }
        var expectedFactories=expectedTrace.Where(token=>token.StartsWith("F:",StringComparison.Ordinal)).ToArray();
        var actualFactories=actualTrace.Where(token=>token.StartsWith("F:",StringComparison.Ordinal)).ToArray();
        if(!expectedFactories.SequenceEqual(actualFactories)){differences.Add("FactoryTrace: expected="+string.Join(",",expectedFactories)+", actual="+string.Join(",",actualFactories));}
        if((long)actual[6]!=0){differences.Add("EnumerableFallback: "+actual[6]);}
        return differences;
    }

    private static object Snapshot(object[] value)=>new{Value=value[0],ExceptionType=value[1],ExceptionMessage=value[2],Trace=value[3],LogicalDelegate=value[4],PhysicalDelegate=value[5],EnumerableFallback=value[6]};

    private static void SaveInputAudit(byte[][] inputs,string[] hashes,string[] originalHashes,int cases){
        var root=ArtifactRoot();
        if(root is null){return;}
        Directory.CreateDirectory(root);
        File.WriteAllText(Path.Combine(root,"input-audit.json"),JsonSerializer.Serialize(new{CaseCount=cases,ExpectedObservationCount=cases*3*2,InputCorrection="System Enumerable alias only; original embedded bytes retained",Inputs=new[]{new{Anchor=false,ByteCount=inputs[0].Length,OriginalSHA256=originalHashes[0],SHA256=hashes[0]},new{Anchor=true,ByteCount=inputs[1].Length,OriginalSHA256=originalHashes[1],SHA256=hashes[1]}},Runtime=Environment.Version.ToString()},new JsonSerializerOptions{WriteIndented=true}));
    }

    private static void SaveGeneration(int anchor,string source,string generated,List<string> diagnostics,List<string> errors,string inputHash,string compileStatus){
        var root=ArtifactRoot();if(root is null){return;}
        var directory=Path.Combine(root,"anchor-"+anchor);Directory.CreateDirectory(directory);
        File.WriteAllText(Path.Combine(directory,"input.cs"),source);
        File.WriteAllText(Path.Combine(directory,"generated.cs"),generated);
        File.WriteAllText(Path.Combine(directory,"generation.json"),JsonSerializer.Serialize(new{Anchor=anchor==1,InputSHA256=inputHash,GeneratedSHA256=Hash(Encoding.UTF8.GetBytes(generated)),GeneratorSHA256=GeneratorHash(),Runtime=Environment.Version.ToString(),SystemLinqAssembly=typeof(Enumerable).Assembly.FullName,Diagnostics=diagnostics,Errors=errors,Compile=compileStatus},new JsonSerializerOptions{WriteIndented=true}));
    }

    private static void SaveRuntime(int anchor,List<object> observations,int count,string inputHash){
        var root=ArtifactRoot();if(root is null){return;}
        var directory=Path.Combine(root,"anchor-"+anchor);Directory.CreateDirectory(directory);
        File.WriteAllText(Path.Combine(directory,"observations.json"),JsonSerializer.Serialize(new{Anchor=anchor==1,InputSHA256=inputHash,ObservationCount=observations.Count,ExpectedObservationCount=207,Observations=observations,Runtime=Environment.Version.ToString(),RuntimeCaptured=true},new JsonSerializerOptions{WriteIndented=true}));
    }

    private static string? ArtifactRoot(){
        var value=Environment.GetEnvironmentVariable("SEAMLESS_LAST_SUPPLEMENT_ARTIFACT_DIR");
        if(string.IsNullOrWhiteSpace(value)){return null;}
        return Path.GetFullPath(value);
    }
    private static string Hash(byte[] bytes)=>Convert.ToHexString(SHA256.HashData(bytes));
    private static string GeneratorHash()=>Hash(File.ReadAllBytes(typeof(global::Seamless.FLinq.Generator.FLinqIncrementalGenerator).Assembly.Location));
}
